// Package render generates the human-readable Markdown views of the catalog
// and the coverage report. Generated files are never edited by hand.
package render

import (
	"fmt"
	"sort"
	"strings"

	"github.com/OI4/oec/spec/tools/internal/catalog"
)

// Views returns the generated Markdown files (relative path -> content).
func Views(s *catalog.Spec) map[string]string {
	out := map[string]string{}
	var idx strings.Builder
	idx.WriteString("<!-- Generated by 'spectool render' – do not edit. -->\n# OEC v2 requirements catalog\n\n")
	fmt.Fprintf(&idx, "Guideline baseline: `%s`. Source of truth: the YAML files in `oec/spec/requirements/` (ADR-0018).\n\n", s.Areas.Baseline)
	idx.WriteString("| Area | Title | Cycle | Status | Requirements | Sections |\n|---|---|---|---|---:|---|\n")
	byArea := map[string]catalog.AreaFile{}
	for _, f := range s.Files {
		byArea[f.Area] = f
	}
	for _, a := range s.Areas.Areas {
		f, ok := byArea[a.Code]
		n := "–"
		name := a.Code
		if ok {
			n = fmt.Sprint(len(f.Requirements))
			name = fmt.Sprintf("[%s](%s)", a.Code, viewName(a.Code))
			out[catalog.ViewDir+"/"+viewName(a.Code)] = area(a, f)
		}
		fmt.Fprintf(&idx, "| %s | %s | %s | %s | %s | %s |\n", name, a.Title, a.Cycle, a.Status, n, strings.Join(a.Sections, ", "))
	}
	out[catalog.ViewDir+"/README.md"] = idx.String()
	return out
}

func viewName(code string) string { return strings.ToLower(code) + ".md" }

func area(a catalog.Area, f catalog.AreaFile) string {
	var b strings.Builder
	fmt.Fprintf(&b, "<!-- Generated by 'spectool render' from %s – do not edit. -->\n", catalog.AreaFileName(a.Code))
	fmt.Fprintf(&b, "# %s – %s\n\n", a.Code, a.Title)
	fmt.Fprintf(&b, "Guideline baseline: `%s` · Area status: %s · Sections: %s\n\n", f.Baseline, a.Status, strings.Join(a.Sections, ", "))
	if a.Notes != "" {
		fmt.Fprintf(&b, "%s\n\n", oneLine(a.Notes))
	}
	b.WriteString("| ID | Title | Keyword | L1 | L2 | L3 | Domain | Verification | Status |\n|---|---|---|---|---|---|---|---|---|\n")
	for _, r := range f.Requirements {
		l1, l2, l3 := "n/a", "n/a", "n/a"
		if r.Levels != nil {
			l1, l2, l3 = r.Levels.L1, r.Levels.L2, r.Levels.L3
		}
		kw := r.Keyword
		if r.Implicit {
			kw += "*"
		}
		fmt.Fprintf(&b, "| [%s](#%s) | %s | %s | %s | %s | %s | %s | %s | %s |\n",
			r.ID, strings.ToLower(r.ID), esc(r.Title), kw, l1, l2, l3, r.Domain, strings.Join(r.Verification, ", "), r.Status)
	}
	b.WriteString("\n\\* implicit: stated without keyword, treated as MUST by the interim rule of SF-035 (G-1.6).\n")
	for _, r := range f.Requirements {
		fmt.Fprintf(&b, "\n## %s\n\n**%s**\n\n%s\n\n", r.ID, esc(r.Title), oneLine(r.Statement))
		kw := r.Keyword
		if r.Implicit {
			kw += " (implicit, SF-035)"
		}
		fmt.Fprintf(&b, "- Keyword: %s\n", kw)
		if r.Levels != nil {
			fmt.Fprintf(&b, "- Levels: L1 %s · L2 %s · L3 %s\n", r.Levels.L1, r.Levels.L2, r.Levels.L3)
		}
		fmt.Fprintf(&b, "- Domain: %s · Applies to: %s\n", r.Domain, strings.Join(r.AppliesTo, ", "))
		if r.Condition != "" {
			fmt.Fprintf(&b, "- Condition: %s\n", oneLine(r.Condition))
		}
		if len(r.Scope) > 0 {
			fmt.Fprintf(&b, "- Scope: %s\n", strings.Join(r.Scope, ", "))
		}
		fmt.Fprintf(&b, "- Refs: %s\n", strings.Join(r.Refs, ", "))
		fmt.Fprintf(&b, "- Verification: %s\n", strings.Join(r.Verification, ", "))
		fmt.Fprintf(&b, "- Status: %s", r.Status)
		if r.ReplacedBy != "" {
			fmt.Fprintf(&b, " (replaced by %s)", r.ReplacedBy)
		}
		b.WriteString("\n")
		if len(r.Inventory) > 0 {
			keys := append([]string(nil), r.Inventory...)
			sort.Strings(keys)
			fmt.Fprintf(&b, "- Inventory: %s\n", strings.Join(keys, ", "))
		}
		for _, q := range r.Quotes {
			fmt.Fprintf(&b, "\n> %s\n> — %s\n", oneLine(q.Text), q.Ref)
		}
		if r.Notes != "" {
			fmt.Fprintf(&b, "\nNotes: %s\n", oneLine(r.Notes))
		}
	}
	return b.String()
}

// oneLine joins the words of s into one line of Markdown prose; see mdText.
func oneLine(s string) string { return mdText(strings.Join(strings.Fields(s), " ")) }

// mdText escapes "<" outside code spans, so that placeholders such as
// <ServiceType> are shown and not swallowed as HTML tags by Markdown viewers.
func mdText(s string) string {
	parts := strings.Split(s, "`")
	for i := range parts {
		// Even parts are outside code spans; after an unmatched backtick the
		// last part is prose as well.
		if i%2 == 0 || (i == len(parts)-1 && len(parts)%2 == 0) {
			parts[i] = strings.ReplaceAll(parts[i], "<", "&lt;")
		}
	}
	return strings.Join(parts, "`")
}

func esc(s string) string { return strings.ReplaceAll(oneLine(s), "|", "\\|") }
